    async fn confirming_fanout_retains_retry_after_authenticated_sync_closes() {
        use crate::{identity::account::Account, node::test_support::node_with_files};
        let dir = tempfile::tempdir().unwrap();
        let holder_identity = DeviceIdentity::generate();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let proof = Announce::new_with_account(
            &holder_identity, &Account::generate(), "holder", listener.local_addr().unwrap().port(),
        );
        let (source, _, _) = node_with_files(
            dir.path(), DeviceIdentity::generate(), Account::generate(), &proof,
        );
        let channel = source.create_channel("retry sync", vec![proof.public()]).await.unwrap();
        let event = source.enqueue_channel_message_reply_expiring_if(
            channel, b"retry me", None, None, |commit| commit(),
        ).unwrap();
        let server = tokio::spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            let mut connection = crate::transport::SecureChannel::accept(stream, &holder_identity).await.unwrap();
            connection.recv().await.unwrap();
            // Authentication succeeded. Lose the exchange after its first real
            // sync frame, rather than testing an earlier dial failure.
        });
        let outcome = source.distribute_channel_targets_outcome(
            channel, &[proof.public()], None, false, Some(event),
        ).await;
        server.await.unwrap();
        assert!(outcome.failed, "a failed sync must reach the distribution owner");
        assert!(outcome.deferred, "the committed fanout must retain its retry ticket");
        assert_eq!(source.channel_custody_count(channel, event).unwrap(), Some(0));
    }

'''
