    async fn sync_and_confirm_custody_admitted(
        self: &Arc<Self>,
        channel: ConversationId,
        event_id: EventId,
        peer: &PeerRecord,
    ) -> Result<u64, super::session::SessionError> {
        let mut conn = self.privacy_sync_dial(peer.addr, &peer.public).await?;
        let before = conn.sent_frame_bytes();
        let store = self.sync_store(conn.peer_identity());
        let _reception = self
            .request_reception_scope(&store, &conn)
            .ok_or(crate::transport::TransportError::AdmissionDenied)?;
        let round = request_round(&mut conn, &store, channel).await;
        self.dispatch_received_sync_work(&store);
        if let Err(error) = round {
            // A failed whole-history exchange cannot establish completion. Its
            // partially consumed connection and reception capacity must retire
            // before an independent exact-message query can be admitted.
            drop(_reception);
            drop(store);
            drop(conn);
            if matches!(error, super::session::SessionError::NoProgress) {
                self.recheck_channel_custody_peer(channel, event_id, peer)
                    .await;
            }
            return Err(error);
        }
        let reusable = {
            match request_durable_have(&mut conn, channel, event_id).await {
                Ok(held) => {
                    if held {
                        let device = peer.public.user_id();
                        let witnessed = self
                            .publish_channel_custody(
                                channel,
                                event_id,
                                &peer.public,
                                true,
                                false,
                                false,
                            )
                            .is_ok();
                        let changed = if witnessed {
                            let mut store =
                                self.channel_custody.lock().expect("channel custody mutex");
                            let before = store.revision();
                            store.confirm(event_id, &device).is_ok() && store.revision() != before
                        } else {
                            false
                        };
                        if changed {
                            self.delivery_status_notify.notify_waiters();
                        }
                    }
                    true
                }
                Err(_) => false,
            }
        };
        let bytes = conn.sent_frame_bytes().saturating_sub(before);
        if reusable {
            self.recycle_sync_channel(conn);
        }
        Ok(bytes)
    }

    /// Periodically verify one old claim without first syncing the missing
    /// event back to that peer. A negative answer retracts the displayed copy;
    /// the normal retry queue may subsequently restore and reconfirm it.
    async fn recheck_one_channel_custody(
        &self,
        cursor: usize,
        after: &mut HashMap<ConversationId, (u64, EventId)>,
        cycles: &mut HashMap<ConversationId, usize>,
    ) {
        let result: Result<(), NodeError> = async {
            let me = self.user_id();
            let author =
                crate::eventlog::event::Author::from_ed25519(self.identity.public().ed25519_pub);
            let mut channels: Vec<_> = {
                let book = self.channels.lock().expect("channels mutex not poisoned");
                book.channel_ids()
                    .into_iter()
                    .filter(|channel| {
                        book.state(channel)
                            .is_some_and(|state| state.is_member(&me) && !state.is_dissolved())
                                    ) || super::session_pool::retryable_sync_error(error)
                                }) {
                                    // A changed local view or closed remote session did
                                    // not finish this round. Keep the journal ticket
                                    // for a fresh view through the existing backoff.
                                    deferred.store(true, std::sync::atomic::Ordering::Relaxed);
                                }
                                Ok::<(), super::session::SessionError>(())
                            }
                        })
                        .await;
                        if !matches!(
                            &result,
                            Ok(Ok(()))
                                | Ok(Err(super::session::SessionError::Transport(
                                    crate::transport::TransportError::AdmissionDenied
                                )))
                        ) {
                            failed.store(true, std::sync::atomic::Ordering::Relaxed);
                        }
                        if let Ok(Err(error)) = result
                            && (matches!(
                                &error,
                                super::session::SessionError::NoProgress
                                    | super::session::SessionError::ResourceUnavailable
                                    | super::session::SessionError::Store(LogError::StaleCursor)
                            ) || super::session_pool::retryable_sync_error(&error)
                                || matches!(&error, super::session::SessionError::Transport(error)
                                    if super::session_pool::local_capacity_busy(error)))
                        {
                            deferred.store(true, std::sync::atomic::Ordering::Relaxed);
                        }
                    }
                })
                .await;
            if replicate_to_post_office {
                let result = self
                    .replicate_to_post_office_targets_observing(
                        channel,
                        members
                            .iter()
                            .filter(|member| member.user_id() != me)
                            .cloned()
                            .collect(),
                        confirming,
                        Some(&failed),
                    )
                    .await;
                if result.is_err() {
                        pushes += 1;
                    }
                    wire => panic!("unexpected first-connection frame: {wire:?}"),
                }
            }
            assert!(connection.recv().await.is_err(), "failed protocol connection must be discarded");
            drop(connection);
            let Ok(Ok((stream, _))) = tokio::time::timeout(std::time::Duration::from_secs(3), listener.accept()).await else {
                return false;
            };
            let mut connection = SecureChannel::accept_with_presence(stream, &holder, Some(&server_proof), |_| true).await.unwrap();
            assert!(matches!(decode(&connection.recv().await.unwrap()).unwrap(),
                SyncWire::DurableHaveRequest { conversation: c, event_id } if c == conversation && event_id == target));
            connection.send(&encode(&SyncWire::DurableHaveResponse {
                conversation, event_id: target, stored: held,
            }).unwrap()).await.unwrap();
            true
        });
        let deferred = source.distribute_channel_confirming(conversation, &[proof.public()], Some(target)).await;
        let fresh_probe = task.await.unwrap();
        assert!(fresh_probe, "NoProgress must not suppress independent exact custody evidence");
        assert_eq!(source.channel_custody_count(conversation, target).unwrap(), Some(usize::from(held)));
        assert!(deferred, "exact custody does not finish the unrelated control fanout");
    }).await.expect("exact custody regression timed out");
}

