                nodes[1..].iter().map(|node| node.identity.public()).collect()).await.unwrap();
            // Both readers receive actual membership and sender-key controls
            // before the measured send. Only the source's live routes change.
            for node in [source, sibling] {
                let access = node.account_group_access(channel).unwrap();
                assert_eq!(access.execution, crate::node::AccountGroupExecution::Local);
                assert!(matches!(access.role, crate::node::AccountGroupRole::Owner | crate::node::AccountGroupRole::Member));
            }
            source.roster.lock().unwrap().forget(&sibling.identity.public());
            source.roster.lock().unwrap().forget(&second.identity.public());
            source.sessions.clear();
            let body = b"Both external accounts retained this one original event";
            source.send_channel_message(channel, body).await.unwrap();
            let event = source.log.lock().unwrap().message_keys_after(channel,
