                .unwrap().into_iter().next().unwrap().1;
            assert!(first.log.lock().unwrap().get(&event).unwrap().is_some());
            assert!(second.log.lock().unwrap().get(&event).unwrap().is_none());
            assert_eq!(source.channel_custody_count(channel, event).unwrap(), Some(1));
            // C and A2 can only pull the original from B. No explicit source
            // distribution or synthetic custody observation is admitted here.
            for reader in [second, sibling] {
                for other in &nodes {
                    if other.user_id() != first.user_id() {
                        reader.roster.lock().unwrap().forget(&other.identity.public());
                    }
                }
                reader.sessions.clear();
                reader.pull_channel_from_members(channel, 0, false).await;
                assert!(reader.log.lock().unwrap().get(&event).unwrap().is_some());
                tokio::time::timeout(Duration::from_secs(8), async {
                    loop {
                        match reader.channel_history(channel, 10) {
                            Ok(rows) if rows.iter().any(|row| row.id == event && row.text == body) => break,
                            Ok(_) | Err(NodeError::Log(LogError::StaleCursor)) => {}
