    pub(in crate::node) fn clear(&self) {
        self.idle.lock().unwrap().clear();
        state.next = token;
        let (send, receive) = tokio::sync::oneshot::channel();
        state.entries.push_back((token, send));
        drop(state);
        self.inbound_idle.changed.notify_waiters();
