                async {
                    let messages = Box::pin(self.pull_delivery_scope(peer, dm, true)).await;
                    let receipts = Box::pin(self.pull_delivery_scope(peer, conv, true)).await;
                    messages.combine(receipts)
                }
            );
            direct.combine(relay)
