            | SyncWire::FpRequestV3(_)
            | SyncWire::FpRequestV4(_)
            | SyncWire::FpRequestV5(_)
            | SyncWire::DurableHaveRequest { .. }
            | SyncWire::FileConsentRequest { .. }
