//! Post-office integration: find the elected post office in the roster, and run
//! the relay's server side (sync rounds over a durable [`PostOffice`]). The
//! Client upload and drain live in `opaque_relay` and `serving`;
//! this module provides election lookup and the serving loop.

use crate::discovery::roster::{PeerRecord, Roster, RouteSource};
use crate::identity::device::{DeviceIdentity, PublicIdentity};
use crate::node::bridge_directory::{self, BridgeDirectory};
use crate::node::session::{Served, serve_one, serve_wire_bytes};
use crate::node::transport::secure_accept;
use crate::postoffice::federation;
use crate::postoffice::gateway::GatewayProof;
use crate::postoffice::{PostOffice, elect};
use crate::transport::SecureChannel;
use std::collections::HashSet;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::io::{AsyncRead, AsyncWrite};
use tokio::net::TcpListener;
use tokio::sync::Semaphore;

/// The post office this node should use: the lowest-fingerprint peer among those
/// advertising the post-office role, or `None` if no post office is known.
/// Deterministic — every node computes the same winner from the same roster.
pub fn elected_post_office(roster: &Roster) -> Option<PeerRecord> {
    let candidates = roster.post_offices();
    let winner = elect(
        &candidates
            .iter()
            .map(|r| r.public.clone())
            .collect::<Vec<_>>(),
    )?;
    candidates.into_iter().find(|r| r.public == winner)
}

/// Order verified post offices for delivery. A configured ID is a preference,
/// never an exclusive mailbox. Without one, use a directly discovered LAN
/// relay before a remote gateway; break ties by fingerprint for stability.
pub fn post_office_candidates(roster: &Roster, preferred_id: Option<&str>) -> Vec<PeerRecord> {
    let mut candidates = roster.post_offices();
    candidates.sort_by_key(|relay| {
        (
            preferred_id != Some(relay.public.user_id().as_str()),
            !relay.has_lan_route(),
            relay.public.user_id(),
        )
    });
    candidates
}

/// Test the first candidate while keeping production I/O on the full ordered list.
#[cfg(test)]
pub fn selected_post_office(roster: &Roster, hub_id: Option<&str>) -> Option<PeerRecord> {
    post_office_candidates(roster, hub_id).into_iter().next()
}

/// Keep the user's preferred relay first. For an introduced recipient, favor
/// reporting relays among the remaining candidates: they may have a shorter
/// route to the recipient. Upload still retries every candidate on failure.
pub fn post_office_candidates_for(
    roster: &Roster,
    preferred_id: Option<&str>,
    recipient: &PublicIdentity,
) -> Vec<PeerRecord> {
    let mut candidates = post_office_candidates(roster, preferred_id);
    if let Some(peer) = roster
        .get(&recipient.user_id())
        .filter(|peer| peer.public == *recipient)
    {
        let introduced_by: Vec<_> = peer
            .routes
            .iter()
            .filter(|route| route.source == RouteSource::PostOffice)
            .map(|route| route.addr)
            .collect();
        if !introduced_by.is_empty() {
            candidates.sort_by_key(|relay| {
                (
                    preferred_id.is_some() && preferred_id != Some(relay.public.user_id().as_str()),
                    !introduced_by.contains(&relay.addr),
                )
            });
        }
    }
    candidates
}

/// Performance never changes candidate eligibility; equal costs retain stable policy order.
fn prioritize_responsive_relays(
    candidates: &mut [PeerRecord],
    preferred: Option<&str>,
    cost: impl Fn(&PeerRecord) -> (bool, Duration),
) {
    candidates.sort_by_cached_key(|relay| {
        let (ready, latency) = cost(relay);
        (
            !ready,
            preferred != Some(relay.public.user_id().as_str()),
            latency,
        )
    });
}

impl super::Node {
    pub fn set_bridge_hub_id(&self, id: Option<&str>) -> Result<(), &'static str> {
        if id
            .is_some_and(|value| value.len() != 32 || !value.bytes().all(|b| b.is_ascii_hexdigit()))
        {
            return Err("bridge hub ID must be a full 32-character hexadecimal fingerprint");
        }
        let new_id = id.map(str::to_ascii_lowercase);
        let changed = {
            let mut hub = self
                .bridge_hub_id
                .lock()
                .expect("bridge hub lock not poisoned");
            let changed = *hub != new_id;
            *hub = new_id;
            changed
        };
        if changed {
            self.clear_bridge_introductions();
            self.storage.database().maintenance_waker().notify();
        }
        self.bridge_notify.notify_one();
        self.delivery_notify.notify_one();
        Ok(())
    }

    pub(in crate::node) fn post_office_candidates(&self, roster: &Roster) -> Vec<PeerRecord> {
        let preferred = self
            .bridge_hub_id
            .lock()
            .expect("bridge hub lock not poisoned");
        let mut candidates = post_office_candidates(roster, preferred.as_deref());
        self.rank_relay_candidates(&mut candidates, preferred.as_deref(), None);
        candidates
    }

    pub(in crate::node) fn post_office_candidates_for(
        &self,
        roster: &Roster,
        recipient: &PublicIdentity,
    ) -> Vec<PeerRecord> {
        let preferred = self
            .bridge_hub_id
            .lock()
            .expect("bridge hub lock not poisoned");
        let mut candidates = post_office_candidates_for(roster, preferred.as_deref(), recipient);
        self.rank_relay_candidates(
            &mut candidates,
            preferred.as_deref(),
            roster
                .get(&recipient.user_id())
                .filter(|record| record.public == *recipient),
        );
        candidates
    }

    fn rank_relay_candidates(
        &self,
        candidates: &mut [PeerRecord],
        preferred: Option<&str>,
        recipient: Option<&PeerRecord>,
    ) {
        let now = std::time::Instant::now();
        prioritize_responsive_relays(candidates, preferred, |relay| {
            let hops = recipient.and_then(|peer| {
                peer.presence_routes(now)
                    .filter(|(route, _, _)| {
                        route.source == RouteSource::PostOffice && route.addr == relay.addr
                    })
                    .filter_map(|(route, _, _)| route.origin_hops)
                    .min()
            });
            let measured = self.sessions.routing_cost(&relay.public, relay.addr);
            let cold = Duration::from_millis(if relay.has_lan_route() { 250 } else { 1000 });
            // The forwarding allowance is a cold topology estimate, never an end-to-end SLA.
            let forwarding = Duration::from_millis(u64::from(hops.unwrap_or(4)) * 50);
            (
                self.relay_retry_due(&relay.public),
                measured.unwrap_or(cold) + forwarding,
            )
            return UpdateOutcome::Rejected;
        }
        self.update_from(
            announce,
            gateway_ip,
            gateway_port,
            self_user_id,
            RouteSource::Gateway,
        )
    }

    /// A signed ordinary peer introduced by a relay. The relay's address is
    /// useful for opaque mailbox delivery but is never a direct peer endpoint.
    /// Post offices need their own verified gateway route instead.
    pub fn update_relayed(
        &mut self,
        announce: &Announce,
        relay: SocketAddr,
        self_user_id: &str,
    ) -> UpdateOutcome {
        if announce.user_id == self_user_id
            || !self.valid_announcement(announce)
            || !self.linked_binding_matches(announce)
            || announce.post_office
            || announce.account_id().is_none()
            || self.peers.get(&announce.user_id).is_some_and(|old| {
                old.public != announce.public() || old.account_id != announce.account_id()
            })
            || self.historical.get(&announce.user_id).is_some_and(|old| {
                old.public() != announce.public() || old.account_id() != announce.account_id()
            })
        {
            return UpdateOutcome::Rejected;
        }
        let now = Instant::now();
        let existing = self.peers.get(&announce.user_id);
        let existed = existing.is_some();
        let name_changed = existing.is_some_and(|peer| peer.name != announce.name);
        let mut routes = existing.map(|peer| peer.routes.clone()).unwrap_or_default();
        let route_changed = !routes
            .iter()
            .any(|route| route.addr == relay && route.source == RouteSource::PostOffice);
        let prior = routes
            .iter()
            .find(|route| route.addr == relay && route.source == RouteSource::PostOffice);
        let prior_expiry = prior.and_then(|route| route.presence_expires_at);
            .filter(|peer| peer.public == undo.public)
        else {
            return;
        };
        peer.routes.retain(|route| {
            !(route.addr == undo.staged.addr
                && route.source == undo.staged.source
                && route.last_seen == undo.staged.last_seen
                && route.last_authenticated == undo.staged.last_authenticated)
        });
        for (index, route) in undo.previous {
            if (!restore_relays && route.source == RouteSource::PostOffice)
                || peer
                    .routes
                    .iter()
                    .any(|current| current.addr == route.addr && current.source == route.source)
            {
                continue;
            }
            // A concurrent discovery may have consumed the restored slot. Keep
            // independently learned routes ahead of the oldest mailbox hint.
            if peer.routes.len() == MAX_ROUTES_PER_PEER {
                let oldest_relay = peer
                    .routes
                    .iter()
                    .enumerate()
                    .filter(|(_, current)| current.source == RouteSource::PostOffice)
                    .min_by_key(|(_, current)| current.last_seen)
                    .map(|(index, _)| index);
                if route.source == RouteSource::PostOffice {
                    continue;
                }
                let Some(oldest_relay) = oldest_relay else {
